public class ClipPlayer:AxHost {
 dynamic player;string pending;public string Failure;
 public ClipPlayer():base("6BF52A52-394A-11d3-B153-00C04F79FAA6"){}
 protected override void AttachInterfaces(){try{player=GetOcx();player.uiMode="none";player.stretchToFit=true;player.enableContextMenu=false;player.settings.enableErrorDialogs=false;player.settings.autoStart=false;player.settings.invokeURLs=false;player.settings.volume=65;if(pending!=null)player.URL=new Uri(pending).AbsoluteUri;}catch(Exception ex){Failure=ex.ToString();player=null;}}
 public bool Ready{get{return player!=null;}}
 public bool Failed{get{try{return player!=null&&player.error.errorCount>0;}catch{return true;}}}
 public bool Playing{get{try{return player!=null&&player.playState==3;}catch{return false;}}}
 public double Position{get{try{return player==null?0:(double)player.controls.currentPosition;}catch{return 0;}}set{try{if(player!=null)player.controls.currentPosition=value;}catch{}}}
 public double Duration{get{try{return player==null?0:(double)player.currentMedia.duration;}catch{return 0;}}}
 public void Open(string path){pending=path;if(player!=null){player.controls.stop();player.error.clearErrorQueue();player.URL=new Uri(path).AbsoluteUri;}}
 public void Play(){if(player!=null)player.controls.play();}
 public void Pause(){try{if(player!=null)player.controls.pause();}catch{}}
 public void ReleaseVideo(){try{if(player!=null){player.controls.stop();player.close();}}catch{}pending=null;}
}

public static class ClipPreview {
 public static Task<double> Probe(string path,string tools,CancellationToken ct){return Task.Run(()=>{
  string exe=Path.Combine(tools,"ffprobe.exe");if(!File.Exists(exe))throw new Exception("ffprobe.exe não foi encontrado na pasta tools.");
  using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(ct))using(var p=new Process()){deadline.CancelAfter(10000);p.StartInfo=new ProcessStartInfo(exe,"-v error -protocol_whitelist file,pipe -show_entries format=duration:stream=codec_type -of json -i "+Engine.Quote(path)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};string output="";p.OutputDataReceived+=delegate(object s,DataReceivedEventArgs e){if(e.Data!=null&&output.Length<1024*1024)output+=e.Data;};p.ErrorDataReceived+=delegate{};p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();using(deadline.Token.Register(delegate{try{p.Kill();}catch{}})){p.WaitForExit();}ct.ThrowIfCancellationRequested();if(deadline.IsCancellationRequested)throw new Exception("A leitura do vídeo demorou demais.");if(p.ExitCode!=0)throw new Exception("Não foi possível ler esse arquivo de vídeo.");var json=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(output);bool video=false;object streams;if(json.TryGetValue("streams",out streams))foreach(var stream in (IEnumerable)streams){var item=stream as Dictionary<string,object>;object kind;if(item!=null&&item.TryGetValue("codec_type",out kind)&&Convert.ToString(kind)=="video")video=true;}object format;double duration;if(!video||!json.TryGetValue("format",out format)||!double.TryParse(Convert.ToString(((Dictionary<string,object>)format)["duration"]),NumberStyles.Float,CultureInfo.InvariantCulture,out duration)||double.IsInfinity(duration)||double.IsNaN(duration)||duration<=0||duration>359999)throw new Exception("Escolha um vídeo gravado com duração de até 99:59:59.");return duration;}
 },ct);}
 public static Task<Image> Frame(string input,double seconds,string tools,CancellationToken ct){return Task.Run(()=>{
  using(var deadline=CancellationTokenSource.CreateLinkedTokenSource(ct))using(var p=new Process()){deadline.CancelAfter(7000);p.StartInfo=new ProcessStartInfo(Path.Combine(tools,"ffmpeg.exe"),"-hide_banner -loglevel error -nostdin -threads 1 -protocol_whitelist file,pipe -ss "+seconds.ToString("0.###",CultureInfo.InvariantCulture)+" -i "+Engine.Quote(input)+" -frames:v 1 -vf scale=640:-2 -threads 1 -f image2pipe -c:v mjpeg pipe:1"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};p.ErrorDataReceived+=delegate{};p.Start();p.BeginErrorReadLine();using(deadline.Token.Register(delegate{try{p.Kill();}catch{}}))using(var buffer=new MemoryStream()){p.StandardOutput.BaseStream.CopyTo(buffer);p.WaitForExit();ct.ThrowIfCancellationRequested();if(deadline.IsCancellationRequested||p.ExitCode!=0||buffer.Length==0)throw new Exception("Prévia indisponível para esse quadro.");buffer.Position=0;using(var image=Image.FromStream(buffer))return (Image)new Bitmap(image);}}
 },ct);}
}

