 }
 static TextBox Box(){return new TextBox{Dock=DockStyle.Fill,BackColor=Color.FromArgb(35,35,35),ForeColor=Color.WhiteSmoke,Margin=new Padding(0,4,4,4)};}
 static FlowLayoutPanel Flow(){return new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,Margin=Padding.Empty,Padding=Padding.Empty};}
 Button Button(string text,Action action){var b=TransferWindow.Button(text,0,0,110);b.Margin=new Padding(0,1,5,0);b.Click+=delegate{try{action();}catch(Exception ex){if(status!=null)status.Text=ex.Message;}};return b;}
 public static string Time(double value){var t=TimeSpan.FromSeconds(Math.Max(0,value));return ((int)t.TotalHours).ToString("00")+":"+t.Minutes.ToString("00")+":"+t.Seconds.ToString("00")+(t.Milliseconds>0?"."+t.Milliseconds.ToString("000"):"");}
 void Choose(){if(busy)return;using(var dialog=new OpenFileDialog{Title="Escolher vídeo para recortar",Filter="Vídeos|*.mp4;*.mkv;*.webm;*.mov;*.avi;*.m4v;*.wmv;*.mpeg;*.mpg;*.ts|Todos os arquivos|*.*"})if(dialog.ShowDialog(FindForm())==DialogResult.OK)OpenFile(dialog.FileName);}
 public void OpenFile(string path){if(busy||closing)return;loadTask=LoadFile(path);}
 async Task LoadFile(string path){int version=++revision;if(loadingCancellation!=null)loadingCancellation.Cancel();PausePreview();if(player!=null)player.ReleaseVideo();source=null;duration=position=0;loading=true;input.Text=path;placeholder.Text="Lendo vídeo…";placeholder.Visible=true;status.Text="Lendo a duração e preparando a prévia…";UpdateActions();var tokenSource=loadingCancellation=new CancellationTokenSource();try{path=Path.GetFullPath(path);if(!File.Exists(path))throw new FileNotFoundException("O vídeo não foi encontrado.");double total=await ClipPreview.Probe(path,tools,tokenSource.Token);if(closing||version!=revision)return;source=path;duration=total;manualOutput=false;start.Text="00:00:00";end.Text=Time(duration);RangeChanged();lastSaved=null;progress.Value=0;EnsurePlayer();if(player!=null&&player.Ready){useFrames=false;player.Visible=true;player.Open(path);}else useFrames=true;placeholder.Visible=false;picture.Visible=useFrames;if(useFrames){if(player!=null)player.Visible=false;picture.BringToFront();}frameTask=UpdateFrame(0);status.Text="Marque o início e o fim. O vídeo original será preservado.";}catch(OperationCanceledException){}catch(Exception ex){if(!closing&&version==revision){status.Text=ex.Message;placeholder.Text="Escolha outro arquivo de vídeo";placeholder.Visible=true;}}finally{if(version==revision){loading=false;if(loadingCancellation==tokenSource)loadingCancellation=null;if(!closing){UpdateActions();UpdatePosition();}}tokenSource.Dispose();}}
 void EnsurePlayer(){if(player!=null)return;try{player=new ClipPlayer{Dock=DockStyle.Fill};((ISupportInitialize)player).BeginInit();preview.Controls.Add(player);((ISupportInitialize)player).EndInit();player.CreateControl();player.BringToFront();}catch(Exception ex){previewFailure=ex.ToString();if(player!=null){preview.Controls.Remove(player);player.Dispose();player=null;}}}
