 void UpdateActions(){bool ready=source!=null&&!loading&&!busy&&!closing;choose.Enabled=!busy&&!closing;start.Enabled=end.Enabled=timeline.Enabled=markStart.Enabled=markEnd.Enabled=ready;output.Enabled=ready;play.Enabled=ready&&player!=null&&player.Ready&&!useFrames;save.Enabled=ready;cancel.Enabled=busy;reveal.Enabled=!busy&&lastSaved!=null&&File.Exists(lastSaved);}
 async Task SaveClip(){if(source==null||busy||closing)return;try{double first=ClipRange.Parse(start.Text),last=ClipRange.Parse(end.Text);ValidateRange(first,last);string destination=Path.GetFullPath(output.Text);if(Path.GetExtension(destination).ToLowerInvariant()!=".mp4")throw new Exception("Escolha um destino com extensão .mp4.");if(string.Equals(source,destination,StringComparison.OrdinalIgnoreCase))throw new Exception("Escolha um destino diferente do original.");if(File.Exists(destination))throw new Exception("Esse arquivo já existe. Escolha outro nome.");PausePreview();busy=true;cutCancellation=new CancellationTokenSource();progress.Value=0;status.Text="Recortando vídeo…";UpdateActions();var updates=new Progress<ConversionProgress>(p=>{if(!closing&&busy){progress.Value=p.Percent;status.Text="Recortando — "+p.Percent+"%";}});await MediaConverter.Convert(new ConversionRequest{Input=source,Output=destination,Format="mp4",Trim=true,Start=first,End=last},tools,updates,cutCancellation.Token);lastSaved=destination;progress.Value=100;status.Text="Clipe salvo. O original foi preservado.";}catch(OperationCanceledException){if(!closing)status.Text="Corte cancelado. O original foi preservado.";}catch(Exception ex){if(!closing)status.Text=ex.Message;}finally{busy=false;if(cutCancellation!=null){cutCancellation.Dispose();cutCancellation=null;}if(!closing)UpdateActions();}}
